INSERT INTO scheme_content (scheme_id, documents_required, application_steps, faqs, helpline_label, helpline_number, official_url, last_reviewed_on, content_source, updated_by, updated_at, version) VALUES ('a1000001-0000-0000-0000-000000000005', '[{"title": "Aadhaar card", "titleGu": "આધાર કાર્ડ", "note": "Identity and address proof", "noteGu": "ઓળખ અને સરનામાનો પુરાવો"}, {"title": "Bank account details", "titleGu": "બેંક ખાતા વિગતો", "note": "Passbook or cancelled cheque for benefit credit", "noteGu": "લાભ જમા માટે પાસબુક અથવા રદ્દ ચેક"}, {"title": "Income certificate", "titleGu": "આવકનો દાખલો", "note": "Issued by competent authority", "noteGu": "સંબંધિત અધિકારી પાસેથી"}, {"title": "Age proof", "titleGu": "ઉંમરનો પુરાવો", "note": "Birth certificate or school leaving certificate", "noteGu": "જન્મ પ્રમાણપત્ર અથવા LC"}, {"title": "Education records", "titleGu": "શિક્ષણના દસ્તાવેજો", "note": "Mark sheets, admission proof and exam score card where applicable", "noteGu": "માર્કશીટ, પ્રવેશ પુરાવો અને પરીક્ષા સ્કોર કાર્ડ"}]', '[{"title": "Check eligibility", "titleGu": "પાત્રતા તપાસો", "detail": "Use the eligibility check with your age, income and other details.", "detailGu": "ઉંમર, આવક અને અન્ય વિગતો સાથે પાત્રતા તપાસનો ઉપયોગ કરો."}, {"title": "Gather documents", "titleGu": "દસ્તાવેજો ભેગા કરો", "detail": "Collect the documents listed for this scheme.", "detailGu": "આ યોજના માટે સૂચિબદ્ધ દસ્તાવેજો ભેગા કરો."}, {"title": "Apply online or at Jan Seva Kendra", "titleGu": "ઑનલાઇન અથવા JSK પર અરજી", "detail": "Submit through Digital Gujarat or visit the nearest Jan Seva Kendra.", "detailGu": "Digital Gujarat દ્વારા અથવા નજીકના JSK પર અરજી કરો."}, {"title": "Track application", "titleGu": "અરજી ટ્રેક કરો", "detail": "Track status in My Applications after login.", "detailGu": "લૉગિન પછી મારી અરજીઓમાં સ્થિતિ જુઓ."}, {"title": "Receive benefit", "titleGu": "લાભ મેળવો", "detail": "Benefit is credited or issued as per scheme rules after approval.", "detailGu": "મંજૂરી પછી યોજના નિયમો મુજબ લાભ મળે છે."}]', '[{"question": "Who can apply?", "questionGu": "કોણ અરજી કરી શકે?", "answer": "See the eligibility section on this page; criteria match the live eligibility engine.", "answerGu": "આ પૃષ્ઠ上的 પાત્રતા વિભાગ જુઓ; માપદંડ લાઇવ પાત્રતા એન્જિન સાથે મેળ ખાય છે."}, {"question": "Is there a fee?", "questionGu": "શુલ્ક છે?", "answer": "Government scheme applications on Digital Gujarat do not charge a portal fee (department fees may apply separately).", "answerGu": "Digital Gujarat પર સરકારી યોજના અરજી માટે પોર્ટલ શુલ્ક નથી."}, {"question": "How long does approval take?", "questionGu": "મંજૂરીમાં કેટલો સમય?", "answer": "Processing time varies by department; track status online after applying.", "answerGu": "વિભાગ મુજબ સમય બદલાય; અરજી પછી ઑનલાઇન સ્થિતિ ટ્રેક કરો."}, {"question": "What is CM Girl Child Education Grant?", "questionGu": "મુખ્યમંત્રી બાળક શિક્ષણ અનુદાન શું છે?", "answer": "See the overview on this page; amounts and rules are defined by the department.", "answerGu": "અવલોકન વિભાગમાં જુઓ; રકમ અને નિયમો વિભાગ દ્વારા નક્કી થાય છે."}]', NULL, NULL, NULL, CURRENT_DATE, 'DEMO_SEED', 'demo-seed', NOW(), 0) ON CONFLICT (scheme_id) DO UPDATE SET documents_required = EXCLUDED.documents_required, application_steps = EXCLUDED.application_steps, faqs = EXCLUDED.faqs, last_reviewed_on = EXCLUDED.last_reviewed_on, content_source = EXCLUDED.content_source, updated_at = NOW(), version = 0;
